import React from 'react';
import styled from 'styled-components';

const MainContainer = styled.div`
  flex: 1;
  min-height: 100vh;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
`;

const BackgroundImage = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('${process.env.PUBLIC_URL}/mobile-charcuterie-cart-1.png');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  z-index: 1;
`;

const Overlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(192, 170, 216, 0.7);
  z-index: 2;
`;

const MissionStatement = styled.div`
  position: relative;
  z-index: 3;
  text-align: center;
  width: 100%;
  max-width: 800px;
  padding: 2rem;
  background: rgba(255, 255, 255, 0.95);
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px);

  h1 {
    font-family: ${({ theme }) => theme.fonts.secondary};
    font-size: 2.5rem;
    color: #786A7F;
    margin-bottom: 1.5rem;
    font-weight: 600;
  }

  p {
    font-size: 1.2rem;
    line-height: 1.8;
    color: #786A7F;
    opacity: 0.9;
  }

  @media (max-width: ${({ theme }) => theme.breakpoints.mobile}) {
    margin: 1rem;
    padding: 1.5rem;

    h1 {
      font-size: 2rem;
    }

    p {
      font-size: 1rem;
    }
  }
`;

export const Home: React.FC = () => {
    return (
        <MainContainer>
            <BackgroundImage />
            <Overlay />
            <MissionStatement>
                <h1>Our Mission</h1>
                <p>
                    At Très Petite LLC, we are dedicated to providing exceptional food and
                    beverage service that delights our customers. Our mission is to create
                    memorable experiences through quality ingredients and outstanding
                    hospitality.
                </p>
            </MissionStatement>
        </MainContainer>
    );
};
